namespace App\Services\Dapcode; use Illuminate\Support\Facades\File; use Illuminate\Support\Str; use Symfony\Component\Finder\Finder; class CodeMinifierService { public function getTargetFiles($target = 'all') { $target = trim((string) $target); $files = []; if (empty($target) || strtolower($target) === 'all') { $files = array_merge( $this->getAegisguardFiles(), $this->getRouteFiles(), $this->getModuleFiles(), $this->getResourceViewFiles() ); return array_values(array_unique($files)); } if (in_array(strtolower($target), ['modules', 'all-modules', 'module-all'], true)) { return $this->getModuleFiles(); } if (in_array(strtolower($target), ['aegisguard', 'protection', 'dapcode', 'core'], true)) { return $this->getAegisguardFiles(); } if (in_array(strtolower($target), ['routes', 'route'], true)) { return $this->getRouteFiles(); } $modulePath = app_path("Modules/{$target}"); if (File::isDirectory($modulePath)) { return $this->getFilesFromDirectory($modulePath); } $modulesDir = app_path('Modules'); if (File::isDirectory($modulesDir)) { $dirs = File::directories($modulesDir); foreach ($dirs as $dir) { if (strcasecmp(basename($dir), $target) === 0) { return $this->getFilesFromDirectory($dir); } } } $absolutePath = $this->isAbsolutePath($target) ? $target : base_path($target); if (File::isFile($absolutePath)) { return [$absolutePath]; } if (File::isDirectory($absolutePath)) { return $this->getFilesFromDirectory($absolutePath); } return []; } public function getAegisguardFiles() { $files = []; $dapcodeServices = app_path('Services/Dapcode'); if (File::isDirectory($dapcodeServices)) { foreach (File::files($dapcodeServices) as $f) { if ($f->getExtension() === 'php') { $files[] = $f->getRealPath(); } } } $dapcodeControllers = app_path('Http/Controllers/Dapcode'); if (File::isDirectory($dapcodeControllers)) { foreach (File::files($dapcodeControllers) as $f) { if ($f->getExtension() === 'php') { $files[] = $f->getRealPath(); } } } $middleware = app_path('Http/Middleware/DapcodeLicenseMiddleware.php'); if (File::isFile($middleware)) { $files[] = realpath($middleware) ? : $middleware; } $commandsPath = app_path('Console/Commands'); if (File::isDirectory($commandsPath)) { $finder = (new Finder()) ->files() ->in($commandsPath) ->name('Dapcode*.php') ->name('SignDapcode*.php') ->name('MakeHMVCModule.php') ->name('RemoveHMVCModule.php') ->name('Code*.php'); foreach ($finder as $f) { $files[] = $f->getRealPath(); } } $coreControllers = app_path('Http/Controllers/Core'); if (File::isDirectory($coreControllers)) { foreach (File::files($coreControllers) as $f) { if ($f->getExtension() === 'php') { $files[] = $f->getRealPath(); } } } $hmvcServices = app_path('Services/HMVC'); if (File::isDirectory($hmvcServices)) { foreach (File::files($hmvcServices) as $f) { if ($f->getExtension() === 'php') { $files[] = $f->getRealPath(); } } } return array_values(array_unique(array_filter($files))); } public function getRouteFiles() { $files = []; $routesPath = base_path('routes'); if (File::isDirectory($routesPath)) { $finder = (new Finder()) ->files() ->in($routesPath) ->name('*.php'); foreach ($finder as $f) { $files[] = $f->getRealPath(); } } return array_values(array_unique($files)); } public function getModuleFiles() { $files = []; $modulesDir = app_path('Modules'); if (File::isDirectory($modulesDir)) { $finder = (new Finder()) ->files() ->in($modulesDir) ->notName('*.enc') ->name(['*.php', 'manifest.json', '*.json']); foreach ($finder as $f) { $files[] = $f->getRealPath(); } } return array_values(array_unique($files)); } public function getResourceViewFiles() { $files = []; $viewsDir = resource_path('views'); if (File::isDirectory($viewsDir)) { $finder = (new Finder()) ->files() ->in($viewsDir) ->name('*.blade.php'); foreach ($finder as $f) { $files[] = $f->getRealPath(); } } return array_values(array_unique($files)); } public function getFilesFromDirectory($dir) { $files = []; if (File::isDirectory($dir)) { $finder = (new Finder()) ->files() ->in($dir) ->notName('*.enc') ->name(['*.php', 'manifest.json', '*.json']); foreach ($finder as $f) { $files[] = $f->getRealPath(); } } return array_values(array_unique($files)); } public function minifyPhp($content, $filePath = '') { if ( ! empty($filePath) && File::isFile($filePath)) { $minified = @php_strip_whitespace($filePath); if ( ! empty($minified)) { return $minified; } } $tempFile = tempnam(sys_get_temp_dir(), 'dap_php_'); File::put($tempFile, $content); $minified = @php_strip_whitespace($tempFile); @unlink($tempFile); return ! empty($minified) ? $minified : $content; } public function minifyJson($content) { $decoded = json_decode($content, true); if ($decoded !== null) { return json_encode($decoded, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); } $content = preg_replace('/\s+/', ' ', $content); $content = preg_replace('/\s*([\{\}\[\]:,])\s*/', '$1', $content); return trim($content); } public function minifyBlade($content) { if (empty($content)) { return ''; } $placeholders = []; $content = preg_replace_callback('/<style\b[^>]*>([\s\S]*?)<\/style>/i', function($m) { $attrs = ''; if (preg_match('/<style\b([^>]*)>/i', $m[0], $am)) { $attrs = $am[1]; } $css = $m[1]; $css = preg_replace('/\/\*[\s\S]*?\*\//', '', $css); $css = preg_replace('/\s+/', ' ', $css); $css = preg_replace('/\s*([:;,{}])\s*/', '$1', $css); return '<style' . $attrs . '>' . trim($css) . '</style>'; }, $content); $content = preg_replace_callback('/<script\b[^>]*>([\s\S]*?)<\/script>/i', function($m) { $attrs = ''; if (preg_match('/<script\b([^>]*)>/i', $m[0], $am)) { $attrs = $am[1]; } $js = $m[1]; $js = preg_replace('/\/\*[\s\S]*?\*\//', '', $js); $lines = explode("\n", $js); $cleanLines = []; foreach ($lines as $line) { $trimmed = trim($line); if ($trimmed === '' || strpos($trimmed, '//') === 0) { continue; } $trimmed = preg_replace('/(?<!:)\s*\/\/[^"\']*$/', '', $trimmed); if ($trimmed !== '') { $cleanLines[] = $trimmed; } } $js = implode(" ", $cleanLines); return '<script' . $attrs . '>' . $js . '</script>'; }, $content); $content = preg_replace_callback('/<(pre|textarea|code)\b[^>]*>.*?<\/\1>/is', function ($matches) use ( & $placeholders) { $key = '___DAP_PROTECTED_BLOCK_' . count($placeholders) . '___'; $placeholders[$key] = $matches[0]; return $key; } , $content); $content = preg_replace_callback('/@php\b([\s\S]*?)@endphp/i', function ($matches) use ( & $placeholders) { $phpCode = trim($matches[1]); $tokens = @token_get_all('<?php ' . $phpCode); $cleanPhp = ''; foreach ($tokens as $token) { if (is_array($token)) { if ($token[0] === T_OPEN_TAG) { continue; } if ($token[0] === T_COMMENT || $token[0] === T_DOC_COMMENT) { continue; } if ($token[0] === T_WHITESPACE) { $cleanPhp .= ' '; continue; } $cleanPhp .= $token[1]; } else { $cleanPhp .= $token; } } $singleLinePhp = preg_replace('/\s+/', ' ', trim($cleanPhp)); $key = '___DAP_PHP_BLOCK_' . count($placeholders) . '___'; $placeholders[$key] = '@php ' . $singleLinePhp . ' @endphp'; return $key; } , $content); $content = preg_replace('/\{\{--[\s\S]*?--\}\}/', '', $content); $content = preg_replace('/<!--(?!\s*\[if[\s\S]*?\])[\s\S]*?-->/', '', $content); $content = preg_replace('/\s+/', ' ', $content); $content = preg_replace('/>\s+</', '><', $content); $content = preg_replace('/>\s+(\{\{|\{!!)/', '>$1', $content); $content = preg_replace('/(\}\}|\!\})\s+</', '$1<', $content); foreach ($placeholders as $key => $originalBlock) { $content = str_replace($key, $originalBlock, $content); } return trim($content); } public function minifyFile($filePath, $createBackup = true) { if ( ! File::isFile($filePath)) { return [ 'success' => false, 'file' => $filePath, 'message' => 'File tidak ditemukan.', ]; } $originalContent = File::get($filePath); $originalSize = strlen($originalContent); $isBlade = Str::endsWith($filePath, '.blade.php'); $isJson = Str::endsWith($filePath, '.json'); if ($isJson) { $minifiedContent = $this->minifyJson($originalContent); $type = 'json_manifest'; } elseif ($isBlade) { $minifiedContent = $this->minifyBlade($originalContent); $type = 'blade_view'; } else { $minifiedContent = $this->minifyPhp($originalContent, $filePath); $type = 'php_code'; } $minifiedSize = strlen($minifiedContent); if ($createBackup) { SourceMapVaultService::storeMap($filePath, $originalContent, $minifiedContent); } File::put($filePath, $minifiedContent); $coreFiles = IntegrityService::getCoreFiles(); if (in_array($filePath, $coreFiles, true) || Str::contains($filePath, 'Services' . DIRECTORY_SEPARATOR . 'Dapcode')) { IntegrityService::recordCoreFilesManifest(); } $savedBytes = max(0, $originalSize - $minifiedSize); $savedPercent = $originalSize > 0 ? round(($savedBytes / $originalSize) * 100, 2) : 0; return [ 'success' => true, 'file' => $filePath, 'type' => $type, 'original_size' => $originalSize, 'minified_size' => $minifiedSize, 'saved_bytes' => $savedBytes, 'saved_percent' => $savedPercent, ]; } public function getFileStatus($filePath) { if ( ! File::isFile($filePath)) { return null; } $content = File::get($filePath); $size = strlen($content); $lines = substr_count($content, "\n") + 1; $isBlade = Str::endsWith($filePath, '.blade.php'); $isJson = Str::endsWith($filePath, '.json'); if ($isJson) { $type = 'JSON'; $isMinified = ($lines <= 1 && $size > 0); } elseif ($isBlade) { $type = 'Blade'; $avgLineLen = $size / max(1, $lines); $isMinified = ($lines <= 3 && $size > 50) || ($lines <= 15 && $size > 1500 && $avgLineLen > 250); } else { $type = 'PHP'; $avgLineLen = $size / max(1, $lines); $isMinified = ($lines <= 3 && $size > 100) || ($lines <= 10 && $size > 2000 && $avgLineLen > 250); } $hasVault = SourceMapVaultService::hasMap($filePath); $relPath = str_replace('\\', '/', Str::after($filePath, base_path() . DIRECTORY_SEPARATOR)); return [ 'file' => $filePath, 'rel_path' => $relPath, 'type' => $type, 'is_minified' => $isMinified, 'status' => $isMinified ? 'MINIFIED' : 'ORIGINAL', 'lines' => $lines, 'size' => $size, 'has_vault' => $hasVault, ]; } protected function isAbsolutePath($path) { return (bool) preg_match('#^([a-zA-Z]:[\\\\/]|/)#', $path); } }